package dev.workshopvideo;
import android.app.Activity;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.content.*;import org.json.*;
/** Same renderer and sensors as real wallpaper, without applying anything to the system. */
public final class WallpaperPreviewActivity extends Activity {
 private WallpaperRenderer renderer;private MotionInput input;private TextureView texture;private Surface surface;private JSONObject config;private String id;private boolean resumed;private TextView status,pageLabel;private LinearLayout pageControls;private float scroll=.5f;private int pages;private SeekBar page;private final dev.workshopvideo.core.LauncherPaging paging=new dev.workshopvideo.core.LauncherPaging();private boolean updatingPage;
 private boolean powerWatching;
 private final BroadcastReceiver powerEvents=new BroadcastReceiver(){public void onReceive(Context c,Intent i){updatePreviewPower();}};
 private void updatePreviewPower(){PowerManager p=getSystemService(PowerManager.class);boolean saving=p!=null&&p.isPowerSaveMode();if(renderer!=null)renderer.powerSaving(saving);if(input!=null&&config!=null)input.active(resumed&&config.optJSONObject("effects").optBoolean("gyro")&&!(saving&&config.optJSONObject("effects").optBoolean("batteryStatic",true)));}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle state){super.onCreate(state);try{
  id=getIntent().getStringExtra("id");if(id==null)throw new IllegalStateException("缺少预览内容");VideoApp app=(VideoApp)getApplication();app.job(id);config=new JSONObject();JSONObject effects=EffectOptions.normalize(new JSONObject(getIntent().getStringExtra("effects")));boolean pan=effects.optBoolean("pan")&&getIntent().getIntExtra("scope",0)!=1&&(!getIntent().getBooleanExtra("fit",false)||effects.optString("alignment").equals("free"));VideoApp.put(effects,"pan",pan);VideoApp.put(config,"effects",effects);VideoApp.put(config,"fit",getIntent().getBooleanExtra("fit",false));VideoApp.put(config,"pan",pan);
  FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);texture=new TextureView(this);root.addView(texture,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);controls.setPadding(dp(18),dp(10),dp(18),dp(20));controls.setBackgroundColor(0xb3101824);status=new TextView(this);status.setText("倾斜手机或拖动画面查看效果");status.setTextSize(12);status.setTextColor(Ui.MUTED);controls.addView(status);
  pageControls=new LinearLayout(this);pageControls.setOrientation(1);pageControls.setVisibility(View.GONE);pageLabel=new TextView(this);pageLabel.setText("模拟桌面翻页 · 中间页（非播放进度）");pageLabel.setTextSize(12);pageLabel.setTextColor(Ui.ACCENT);pageControls.addView(pageLabel);pages=effects.optString("pageMode").equals("manual")?effects.optInt("fallbackPages",3):3;pages=Math.max(1,pages);paging.pages(pages);paging.manual(true);page=new SeekBar(this);page.setMax(Math.max(1,pages-1)*1000);page.setProgress(page.getMax()/2);pageLabel.setText("模拟桌面翻页 · 第 "+(Math.round(scroll*(pages-1))+1)+" / "+pages+" 页（非播放进度）");page.setContentDescription("模拟桌面翻页，不是播放进度");page.setProgressTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));page.setThumbTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));page.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){scroll=p/(float)b.getMax();if(!updatingPage)paging.position(scroll);pageLabel.setText("模拟桌面翻页 · 第 "+(Math.round(scroll*(pages-1))+1)+" / "+pages+" 页（非播放进度）");if(renderer!=null&&!updatingPage)renderer.offset(scroll);}});pageControls.addView(page);LinearLayout turns=new LinearLayout(this);for(int direction:new int[]{-1,1}){Button turn=new Button(this);turn.setText(direction<0?"‹ 上一页":"下一页 ›");turn.setTextColor(Ui.TEXT);turn.setBackground(AppSheet.background(Ui.PANEL,dp(10)));turn.setOnClickListener(v->{int current=Math.round(scroll*(pages-1));page.setProgress(Math.max(0,Math.min(pages-1,current+direction))*1000);});LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,dp(36),1);tp.setMargins(dp(3),dp(2),dp(3),0);turns.addView(turn,tp);}pageControls.addView(turns);controls.addView(pageControls);
  Button close=new Button(this);close.setText("返回设置");close.setAllCaps(false);close.setTextColor(0xff15362c);close.setBackground(AppSheet.background(Ui.ACCENT,dp(14)));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(40));bp.topMargin=dp(8);controls.addView(close,bp);close.setOnClickListener(v->finish());root.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));
  root.setOnApplyWindowInsetsListener((v,i)->{controls.setPadding(dp(18)+i.getSystemWindowInsetLeft(),dp(10),dp(18)+i.getSystemWindowInsetRight(),dp(10)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  input=new MotionInput(this,(x,y)->{if(renderer!=null)renderer.tilt(x,y);},message->runOnUiThread(()->status.setText(message)));texture.setOnTouchListener((v,e)->{float x=e.getX()/Math.max(1,texture.getWidth()),y=e.getY()/Math.max(1,texture.getHeight());int action=e.getActionMasked();if(config.optBoolean("pan")&&paging.touch(x,y,action,SystemClock.elapsedRealtime())){scroll=paging.value();if(renderer!=null)renderer.offset(scroll,action==MotionEvent.ACTION_MOVE);updatingPage=true;page.setProgress(Math.round(scroll*page.getMax()));updatingPage=false;}if(renderer!=null)renderer.touch(x,y,action);return true;});
  texture.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){surface=new Surface(t);start();}public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){if(renderer!=null)renderer.resize(w,h);}public boolean onSurfaceTextureDestroyed(SurfaceTexture t){stop();if(surface!=null){surface.release();surface=null;}return true;}public void onSurfaceTextureUpdated(SurfaceTexture t){}});
 }catch(Exception e){finish();}}
 private void start(){if(!resumed||surface==null||renderer!=null)return;VideoApp app=(VideoApp)getApplication();renderer=new WallpaperRenderer(this,new WallpaperRenderer.Events(){public void contentSize(int w,int h){runOnUiThread(()->{JSONObject o=config.optJSONObject("effects");android.util.DisplayMetrics d=getResources().getDisplayMetrics();pages=dev.workshopvideo.core.DesktopPages.resolve(o.optString("pageMode").equals("manual"),o.optInt("fallbackPages",3),WallpaperStore.prefs(WallpaperPreviewActivity.this).getInt("launcherPages",0),w,h,d.widthPixels,d.heightPixels,(float)o.optDouble("zoom",1));paging.pages(pages);paging.manual(true);if(pages<=1){scroll=.5f;paging.position(.5f);if(renderer!=null)renderer.offset(.5f,true);pageControls.setVisibility(View.GONE);}updatingPage=true;page.setMax(Math.max(1,pages-1)*1000);page.setProgress(Math.round(scroll*page.getMax()));updatingPage=false;pageLabel.setText("模拟桌面翻页 · 第 "+(Math.round(scroll*(pages-1))+1)+" / "+pages+" 页（非播放进度）");});}public void rendered(){}public void pagingAvailable(boolean available){runOnUiThread(()->pageControls.setVisibility(available&&pages>1?View.VISIBLE:View.GONE));}public void failed(String message){runOnUiThread(()->status.setText(message));}});renderer.surfaceFile(surface,texture.getWidth(),texture.getHeight(),app.video(id),config,true);renderer.offset(scroll);updatePreviewPower();}
 private void stop(){if(input!=null)input.active(false);if(renderer!=null){renderer.closeAsync();renderer=null;}}
 protected void onResume(){super.onResume();resumed=true;if(!powerWatching){IntentFilter f=new IntentFilter(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED);if(Build.VERSION.SDK_INT>=33)registerReceiver(powerEvents,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(powerEvents,f);powerWatching=true;}start();updatePreviewPower();}protected void onPause(){resumed=false;if(powerWatching){unregisterReceiver(powerEvents);powerWatching=false;}stop();super.onPause();}protected void onDestroy(){stop();if(surface!=null)surface.release();super.onDestroy();}
}
